import{_ as a,a0 as d,w as r,s as p,ao as n,I as s,a1 as l,A as o,x as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"Linux 终端下的多媒体应用 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 终端下的多媒体应用 | LCTT (201802) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 终端下的多媒体应用 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 终端下的多媒体应用 | LCTT (201802) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201802/20180111 Multimedia Apps for the Linux Console","title":"Linux 终端下的多媒体应用","tag":"201802","desc":""},"relativePath":"201802/20180111 Multimedia Apps for the Linux Console.md","filePath":"[post].md"}'),u={name:"201802/20180111 Multimedia Apps for the Linux Console.md"};function b(f,e,g,m,c,k){const t=d("Link");return r(),p("div",null,[e[38]||(e[38]=n(`<h1 id="linux-终端下的多媒体应用" tabindex="-1">Linux 终端下的多媒体应用 <a class="header-anchor" href="#linux-终端下的多媒体应用" aria-label="Permalink to “Linux 终端下的多媒体应用”">​</a></h1><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/multimedia.jpg?itok=v-XrnKRB" alt=""></p><blockquote><p>Linux 终端是支持多媒体的，所以你可以在终端里听音乐，看电影，看图片，甚至是阅读 PDF。</p></blockquote><p>在我的上一篇文章里，我们了解到 Linux 终端是可以支持多媒体的。是的，这是真的！你可以使用 Mplayer、fbi 和 fbgs 来实现不打开 X 会话就听音乐、看电影、看照片，甚至阅读 PDF。此外，你还可以通过 CMatrix 来体验黑客帝国（Matrix）风格的屏幕保护。</p><p>不过你可能需要对系统进行一些修改才能达到前面这些目的。下文的操作都是在 Ubuntu 16.04 上进行的。</p><h3 id="mplayer" tabindex="-1">MPlayer <a class="header-anchor" href="#mplayer" aria-label="Permalink to “MPlayer”">​</a></h3><p>你可能会比较熟悉功能丰富的 MPlayer。它支持几乎所有格式的视频与音频，并且能在绝大部分现有的平台上运行，像 Linux、Android、Windows、Mac、Kindle、OS/2 甚至是 AmigaOS。不过，要在你的终端运行 MPlayer 可能需要多做一点工作，这些工作与你使用的 Linux 发行版有关。来，我们先试着播放一个视频：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mplayer [视频文件名]</span></span></code></pre></div><p>如果上面的命令正常执行了，那么很好，接下来你可以把时间放在了解 MPlayer 的常用选项上了，譬如设定视频大小等。但是，有些 Linux 发行版在对<ruby>帧缓冲<rt>framebuffer</rt></ruby>的处理方式上与早期的不同，那么你就需要进行一些额外的设置才能让其正常工作了。下面是在最近的 Ubuntu 发行版上需要做的一些操作。</p><p>首先，将你自己添加到 <code>video</code> 用户组。</p><p>其次，确认 <code>/etc/modprobe.d/blacklist-framebuffer.conf</code> 文件中包含这样一行：<code>#blacklist vesafb</code>。这一行应该默认被注释掉了，如果不是的话，那就手动把它注释掉。此外的其他模块行需要确认没有被注释，这样设置才能保证其他那些模块不会被载入。注：如果你想要更深入的利用<ruby>帧缓冲<rt>framebuffer</rt></ruby>，这些针对你的显卡的模块可以使你获得更好的性能。</p><p>然后，在 <code>/etc/initramfs-tools/modules</code> 的结尾增加两个模块：<code>vesafb</code> 和 <code>fbcon</code>，并且更新 iniramfs 镜像：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo nano /etc/initramfs-tools/modules</span></span>
<span class="line"><span> # List of modules that you want to include in your initramfs.</span></span>
<span class="line"><span> # They will be loaded at boot time in the order below.</span></span>
<span class="line"><span> fbcon</span></span>
<span class="line"><span> vesafb</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ sudo update-initramfs -u</span></span></code></pre></div>`,13)),s("p",null,[l(t,{href:"https://www.mjmwired.net/kernel/Documentation/fb/fbcon.txt"},{default:o(()=>[...e[0]||(e[0]=[i("fbcon",-1)])]),_:1}),e[1]||(e[1]=i(" 是 Linux ",-1)),e[2]||(e[2]=s("ruby",null,[i("帧缓冲"),s("rt",null,"framebuffer")],-1)),e[3]||(e[3]=i("终端，它运行在",-1)),e[4]||(e[4]=s("ruby",null,[i("帧缓冲"),s("rt",null,"framebuffer")],-1)),e[5]||(e[5]=i("之上并为其增加图形功能。而它需要一个",-1)),e[6]||(e[6]=s("ruby",null,[i("帧缓冲"),s("rt",null,"framebuffer")],-1)),e[7]||(e[7]=i("设备，这则是由 ",-1)),e[8]||(e[8]=s("code",null,"vesafb",-1)),e[9]||(e[9]=i(" 模块来提供的。",-1))]),e[39]||(e[39]=n('<p>接下来，你需要修改你的 GRUB2 配置。在 <code>/etc/default/grub</code> 中你将会看到类似下面的一行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GRUB_CMDLINE_LINUX_DEFAULT=&quot;quiet splash&quot;</span></span></code></pre></div><p>它也可能还会有一些别的参数，不用管它，在其后加上 <code>vga=789</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GRUB_CMDLINE_LINUX_DEFAULT=&quot;quiet splash vga=789&quot;</span></span></code></pre></div><p>重启之后进入你的终端（<code>Ctrl+Alt+F1</code>）（LCTT 译注：在某些发行版中 <code>Ctrl+Alt+F1</code> 默认为图形界面，可以尝试 <code>Ctrl+Alt+F2</code>），然后就可以尝试播放一个视频了。下面的命令指定了 <code>fbdev2</code> 为视频输出设备，虽然我还没弄明白如何去选择用哪个输入设备，但是我用它成功过。默认的视频大小是 320x240，在此我给缩放到了 960：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mplayer -vo fbdev2 -vf scale -zoom -xy 960 AlienSong_mp4.mov</span></span></code></pre></div><p>来看图 1。粗糙的画面是由于我原视频的质量不高，而不是 MPlayer 的显示问题。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/floated_images/public/fig-1_3.jpg?itok=PtSoKepn" alt="图 1 播放视频"></p><p>MPlayer 可以播放 CD、DVD 以及网络视频流，并且还有一系列的回放选项，这些将作为作业留给大家自己去发现。</p><h3 id="fbi-图片查看器" tabindex="-1">fbi 图片查看器 <a class="header-anchor" href="#fbi-图片查看器" aria-label="Permalink to “fbi 图片查看器”">​</a></h3>',10)),s("p",null,[e[11]||(e[11]=s("code",null,"fbi",-1)),e[12]||(e[12]=i(" 是一个帧缓冲图片查看器。在大部分的 Linux 发行版中，它被包含在 ",-1)),l(t,{href:"https://www.kraxel.org/blog/linux/fbida/"},{default:o(()=>[...e[10]||(e[10]=[i("fbida",-1)])]),_:1}),e[13]||(e[13]=i(" 包里。它原生支持一些常见的图片格式，而如果你安装了 ",-1)),e[14]||(e[14]=s("code",null,"convert",-1)),e[15]||(e[15]=i("（来自于 Image Magick），那么它还能借此打开一些其他格式。最简单的用法是用来查看一个图片文件：",-1))]),e[40]||(e[40]=n('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fbi 文件名</span></span></code></pre></div><p>你可以使用方向键来在大图片中移动视野，使用 <code>+</code> 和 <code>-</code> 来缩放，或者使用 <code>r</code> 或 <code>l</code> 来向右或向左旋转 90 度。<code>Escape</code> 键则可以关闭查看的图片。此外，你还可以给 <code>fbi</code> 一个文件列表来实现幻灯播放：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fbi --list 文件列表.txt</span></span></code></pre></div><p><code>fbi</code> 还支持自动缩放。还可以使用 <code>-a</code> 选项来控制缩放比例。<code>--autoup</code> 和 <code>--autodown</code> 则是用于告知 <code>fbi</code> 只进行放大或者缩小。要调整图片切换时淡入淡出的时间则可以使用 <code>--blend [时间]</code> 来指定一个以毫秒为单位的时间长度。使用 <code>k</code> 和 <code>j</code> 键则可以切换文件列表中的上一张或下一张图片。</p><p><code>fbi</code> 还提供了命令来为你浏览过的文件创建文件列表，或者将你的命令导出到文件中，以及一系列其它很棒的选项。你可以通过 <code>man fbi</code> 来查阅完整的选项列表。</p><h3 id="cmatrix-终端屏保" tabindex="-1">CMatrix 终端屏保 <a class="header-anchor" href="#cmatrix-终端屏保" aria-label="Permalink to “CMatrix 终端屏保”">​</a></h3>',6)),s("p",null,[e[17]||(e[17]=s("ruby",null,[i("黑客帝国"),s("rt",null,"The Matrix")],-1)),e[18]||(e[18]=i("屏保仍然是我非常喜欢的屏保之一（如图 2），仅次于",-1)),e[19]||(e[19]=s("ruby",null,[i("弹跳牛"),s("rt",null,"bouncing cow")],-1)),e[20]||(e[20]=i("。",-1)),l(t,{href:"http://www.asty.org/cmatrix/"},{default:o(()=>[...e[16]||(e[16]=[i("CMatrix",-1)])]),_:1}),e[21]||(e[21]=n(" 可以在终端运行。要运行它只需输入 <code>cmatrix</code>，然后可以用 <code>Ctrl+C</code> 来停止运行。执行 <code>cmatrix -s</code> 则会启动屏保模式，这样的话，按任意键都会直接退出。<code>-C</code> 参数可以设定颜色，譬如绿色（<code>green</code>）、红色（<code>red</code>）、蓝色（<code>blue</code>）、黄色（<code>yellow</code>）、白色（<code>white</code>）、紫色（<code>magenta</code>）、青色（<code>cyan</code>）或者黑色（<code>black</code>）。",25))]),e[41]||(e[41]=n('<p><img src="https://www.linux.com/sites/lcom/files/styles/floated_images/public/fig-2_0.jpg?itok=E3f26R7w" alt="图 2 黑客帝国屏保"></p><p>CMatrix 还支持异步按键，这意味着你可以在它运行的时候改变设置选项。</p><p><code>-B</code> 设置全部使用粗体，而 <code>-b</code>（LCTT 译注：原文误为 <code>-B</code>）则可以设置部分字体加粗。</p><h3 id="fbgs-pdf-阅读器" tabindex="-1">fbgs PDF 阅读器 <a class="header-anchor" href="#fbgs-pdf-阅读器" aria-label="Permalink to “fbgs PDF 阅读器”">​</a></h3><p>看起来，PDF 文档是普遍流行且无法避免的，而且 PDF 比它之前的功能好了很多，譬如超链接、复制粘贴以及更好的文本搜索功能等。<code>fbgs</code> 是 <code>fbida</code> 包中提供的一个 PDF 阅读器。它可以设置页面大小、分辨率、指定页码以及绝大部分 <code>fbi</code> 所提供的选项，当然除了一些在 <code>man fbgs</code> 中列举出来的不可用选项。我主要用到的选项是页面大小，你可以选择 <code>-l</code>、<code>xl</code> 或者 <code>xxl</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fbgs -xl annoyingpdf.pdf</span></span></code></pre></div>',6)),s("p",null,[e[23]||(e[23]=i("欢迎通过 Linux 基金会与 edX 免费提供的",-1)),l(t,{href:"https://training.linuxfoundation.org/linux-courses/system-administration-training/introduction-to-linux"},{default:o(()=>[...e[22]||(e[22]=[i("“Linux 入门”",-1)])]),_:1}),e[24]||(e[24]=i("课程学习更多 Linux 知识。",-1))]),e[42]||(e[42]=s("hr",null,null,-1)),s("p",null,[e[26]||(e[26]=i("via: ",-1)),l(t,{href:"https://www.linux.com/learn/intro-to-linux/2018/1/multimedia-apps-linux-console"},{default:o(()=>[...e[25]||(e[25]=[i("https://www.linux.com/learn/intro-to-linux/2018/1/multimedia-apps-linux-console",-1)])]),_:1})]),s("p",null,[e[30]||(e[30]=i("作者：",-1)),l(t,{href:"https://www.linux.com/users/cschroder"},{default:o(()=>[...e[27]||(e[27]=[i("Carla Schroder",-1)])]),_:1}),e[31]||(e[31]=i(" 译者：",-1)),l(t,{href:"https://github.com/Yinr"},{default:o(()=>[...e[28]||(e[28]=[i("Yinr",-1)])]),_:1}),e[32]||(e[32]=i(" 校对：",-1)),l(t,{href:"https://github.com/wxy"},{default:o(()=>[...e[29]||(e[29]=[i("wxy",-1)])]),_:1})]),s("p",null,[e[35]||(e[35]=i("本文由 ",-1)),l(t,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[33]||(e[33]=[i("LCTT",-1)])]),_:1}),e[36]||(e[36]=i(" 原创编译，",-1)),l(t,{href:"https://linux.cn/"},{default:o(()=>[...e[34]||(e[34]=[i("Linux中国",-1)])]),_:1}),e[37]||(e[37]=i(" 荣誉推出",-1))])])}const y=a(u,[["render",b]]);export{C as __pageData,y as default};
